// Initialize due diligence process with standard structure
const data = $input.item.json;

// Create a structured due diligence object
const dueDiligence = {
  id: `DD-${Date.now()}`,
  companyName: data.companyName,
  founderName: data.founderName,
  founderEmail: data.founderEmail,
  industry: data.industry || '',
  stage: data.stage || '',
  investmentAmount: data.investmentAmount || '',
  valuation: data.valuation || '',
  dateStarted: new Date().toISOString(),
  status: 'Started',
  currentPhase: 'Initial Review',
  completedPhases: [],
  assignedTeam: data.assignedTeam || ['partner1@vcfirm.com', 'associate1@vcfirm.com'],
  leadAssignee: data.leadAssignee || 'associate1@vcfirm.com',
  dueDiligenceChecklist: [
    { category: 'Team', items: [
      { name: 'Founder Background Check', status: 'Pending', assignee: '', notes: '' },
      { name: 'Team Composition Analysis', status: 'Pending', assignee: '', notes: '' },
      { name: 'Reference Checks', status: 'Pending', assignee: '', notes: '' }
    ]},
    { category: 'Market', items: [
      { name: 'Market Size Analysis', status: 'Pending', assignee: '', notes: '' },
      { name: 'Competitive Landscape', status: 'Pending', assignee: '', notes: '' },
      { name: 'Growth Trends', status: 'Pending', assignee: '', notes: '' }
    ]},
    { category: 'Product', items: [
      { name: 'Product Demo', status: 'Pending', assignee: '', notes: '' },
      { name: 'Technology Assessment', status: 'Pending', assignee: '', notes: '' },
      { name: 'IP Review', status: 'Pending', assignee: '', notes: '' }
    ]},
    { category: 'Business', items: [
      { name: 'Business Model Analysis', status: 'Pending', assignee: '', notes: '' },
      { name: 'Financial Review', status: 'Pending', assignee: '', notes: '' },
      { name: 'Customer Interviews', status: 'Pending', assignee: '', notes: '' }
    ]},
    { category: 'Legal', items: [
      { name: 'Corporate Structure Review', status: 'Pending', assignee: '', notes: '' },
      { name: 'Contract Review', status: 'Pending', assignee: '', notes: '' },
      { name: 'Compliance Check', status: 'Pending', assignee: '', notes: '' }
    ]}
  ],
  documents: [],
  meetings: [],
  notes: []
};

// Create folder structure for documents
const folderStructure = {
  mainFolder: `${dueDiligence.companyName} Due Diligence`,
  subFolders: [
    'Team',
    'Market',
    'Product',
    'Business',
    'Legal',
    'Meeting Notes',
    'Final Reports'
  ]
};

return {
  json: {
    dueDiligence,
    folderStructure
  }
};

// Prepare data for creating sub folders
const mainFolderId = $input.first().json.id;
const folderStructure = $input.first().json.folderStructure;

// Create an array of items for the sub folders
const subFolders = folderStructure.subFolders.map(subFolder => {
  return {
    json: {
      subFolder,
      mainFolderId
    }
  };
});

return subFolders;

