parameters.functionCode:
// Check due diligence progress and send reminders
const activeDueDiligence = $input.item.json;

// Calculate days since start
const startDate = new Date(activeDueDiligence.dateStarted);
const currentDate = new Date();
const daysSinceStart = Math.floor((currentDate - startDate) / (1000 * 60 * 60 * 24));

// Check if any reminders need to be sent
let reminderNeeded = false;
let reminderMessage = '';

// Phase duration limits
const phaseDurations = {
  'Initial Review': 5,
  'Detailed Analysis': 10,
  'Final Review': 5
};

// Check if current phase is taking too long
if (phaseDurations[activeDueDiligence.currentPhase]) {
  const phaseLimit = phaseDurations[activeDueDiligence.currentPhase];

  if (daysSinceStart > phaseLimit) {
    reminderNeeded = true;
    reminderMessage = `The ${activeDueDiligence.currentPhase} phase for ${activeDueDiligence.companyName} has exceeded the expected ${phaseLimit} day timeframe. Current duration: ${daysSinceStart} days.`;
  }
}

// Check for incomplete checklist items
let pendingItems = 0;
let totalItems = 0;

if (activeDueDiligence.dueDiligenceChecklist) {
  for (const category of activeDueDiligence.dueDiligenceChecklist) {
    for (const item of category.items) {
      totalItems++;
      if (item.status === 'Pending') {
        pendingItems++;
      }
    }
  }
}

// Calculate completion percentage
const completionPercentage = totalItems > 0 ? Math.round(((totalItems - pendingItems) / totalItems) * 100) : 0;

// Add completion data
activeDueDiligence.completionPercentage = completionPercentage;
activeDueDiligence.pendingItems = pendingItems;
activeDueDiligence.totalItems = totalItems;
activeDueDiligence.daysSinceStart = daysSinceStart;
activeDueDiligence.reminderNeeded = reminderNeeded;
activeDueDiligence.reminderMessage = reminderMessage;

return { json: activeDueDiligence };

