// Update due diligence record to completed status
const dueDiligence = $input.item.json;

// Update status and completion date
dueDiligence.status = 'Completed';
dueDiligence.dateCompleted = new Date().toISOString();
dueDiligence.completedPhases = dueDiligence.completedPhases || [];
dueDiligence.completedPhases.push(dueDiligence.currentPhase);
dueDiligence.currentPhase = 'Completed';

// Calculate duration in days
const startDate = new Date(dueDiligence.dateStarted);
const completionDate = new Date(dueDiligence.dateCompleted);
dueDiligence.durationDays = Math.floor((completionDate - startDate) / (1000 * 60 * 60 * 24));

// Add recommendation from input
dueDiligence.recommendation = $input.first().json.recommendation || 'No recommendation provided';
dueDiligence.recommendationNotes = $input.first().json.recommendationNotes || '';

return { json: dueDiligence };

